function transposeMatrix(matrix) {
  const n = matrix.length;
  return matrix[0].map((_, c) => matrix.map((row) => row[c]));
}

function rotate(matrix) {
  const n = matrix.length;
  for (let i = 0; i < n; i += 1) {
    for (let j = i + 1; j < n; j += 1) {
      const t = matrix[i][j];
      matrix[i][j] = matrix[j][i];
      matrix[j][i] = t;
    }
  }
  for (let i = 0; i < n; i += 1) matrix[i].reverse();
  return matrix;
}

function spiralOrder(matrix) {
  const out = [];
  if (!matrix.length) return out;
  let top = 0;
  let bottom = matrix.length - 1;
  let left = 0;
  let right = matrix[0].length - 1;
  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c += 1) out.push(matrix[top][c]);
    top += 1;
    for (let r = top; r <= bottom; r += 1) out.push(matrix[r][right]);
    right -= 1;
    if (top <= bottom) {
      for (let c = right; c >= left; c -= 1) out.push(matrix[bottom][c]);
      bottom -= 1;
    }
    if (left <= right) {
      for (let r = bottom; r >= top; r -= 1) out.push(matrix[r][left]);
      left += 1;
    }
  }
  return out;
}

function setZeroes(matrix) {
  const rows = matrix.length;
  const cols = matrix[0].length;
  let row0 = false;
  let col0 = false;
  for (let c = 0; c < cols; c += 1) if (matrix[0][c] === 0) row0 = true;
  for (let r = 0; r < rows; r += 1) if (matrix[r][0] === 0) col0 = true;
  for (let r = 1; r < rows; r += 1) {
    for (let c = 1; c < cols; c += 1) {
      if (matrix[r][c] === 0) {
        matrix[r][0] = 0;
        matrix[0][c] = 0;
      }
    }
  }
  for (let r = 1; r < rows; r += 1) {
    for (let c = 1; c < cols; c += 1) {
      if (matrix[r][0] === 0 || matrix[0][c] === 0) matrix[r][c] = 0;
    }
  }
  if (row0) for (let c = 0; c < cols; c += 1) matrix[0][c] = 0;
  if (col0) for (let r = 0; r < rows; r += 1) matrix[r][0] = 0;
  return matrix;
}
